  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_user_accounts_failed_count" CHECK (failed_login_count >= 0),
  CONSTRAINT "chk_user_accounts_password_token" CHECK ((password_token_hash is null) = (password_token_expires_at is null))
);

CREATE TABLE "user_sessions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_account_id" bigint NOT NULL,
  "token_hash" char(64) UNIQUE NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "expires_at" timestamptz NOT NULL,
  CONSTRAINT "chk_user_sessions_expiry" CHECK (expires_at > created_at)
);

