  "external_ref" varchar(200),
  "granularity" usage_granularity,
  "has_daily_activity" boolean,
  "monitoring_since" date NOT NULL DEFAULT (current_date),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_plan_data_sources_connector_only" CHECK (source_type in ('api', 'log')),
  CONSTRAINT "chk_plan_data_sources_granularity" CHECK ((data_type = 'usage') = (granularity is not null)),
  CONSTRAINT "chk_plan_data_sources_daily_activity" CHECK (has_daily_activity is null or (data_type = 'usage' and granularity = 'per_subject'))
);

CREATE TABLE "sync_runs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "connector_id" bigint NOT NULL,
  "trigger" sync_trigger NOT NULL DEFAULT 'scheduled',
  "status" run_status NOT NULL DEFAULT 'running',
  "data_date" date NOT NULL,
  "window_start" timestamptz,
  "window_end" timestamptz,
  "error_message" text,
  "started_at" timestamptz NOT NULL DEFAULT (now()),
  "finished_at" timestamptz,
  CONSTRAINT "chk_sync_runs_finished" CHECK ((status = 'running') = (finished_at is null)),
  CONSTRAINT "chk_sync_runs_duration" CHECK (finished_at is null or finished_at >= started_at),
  CONSTRAINT "chk_sync_runs_window" CHECK (window_end is null or window_start is null or window_end >= window_start),
  CONSTRAINT "chk_sync_runs_error" CHECK ((status = 'failed') = (error_message is not null)),
  CONSTRAINT "chk_sync_runs_paused" CHECK (status <> 'paused' or finished_at = started_at)
);

CREATE TABLE "collection_coverage" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
