CREATE TABLE "import_batches" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "import_type" import_kind NOT NULL,
  "file_id" bigint NOT NULL,
  "target_org_unit_id" bigint,
  "period_from" date,
  "period_to" date,
  "preview_key" uuid UNIQUE NOT NULL,
  "based_on_budget_plan_id" bigint,
  "budget_plan_id" bigint UNIQUE,
  "status" import_status NOT NULL DEFAULT 'previewed',
  "rows_total" int NOT NULL DEFAULT 0,
  "rows_added" int NOT NULL DEFAULT 0,
  "rows_updated" int NOT NULL DEFAULT 0,
  "rows_removed" int NOT NULL DEFAULT 0,
  "rows_rejected" int NOT NULL DEFAULT 0,
  "error_report" jsonb,
  "imported_by" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "confirmed_at" timestamptz,
  CONSTRAINT "chk_import_batches_confirmed" CHECK ((status = 'confirmed') = (confirmed_at is not null)),
  CONSTRAINT "chk_import_batches_budget_target" CHECK ((import_type = 'budget') = (target_org_unit_id is not null and period_from is not null and period_to is not null)),
  CONSTRAINT "chk_import_batches_period" CHECK (period_to is null or period_to >= period_from),
  CONSTRAINT "chk_import_batches_budget_version" CHECK ((budget_plan_id is not null) = (import_type = 'budget' and status = 'confirmed')),
  CONSTRAINT "chk_import_batches_counts" CHECK (rows_total >= 0 and rows_added >= 0 and rows_updated >= 0 and rows_removed >= 0 and rows_rejected >= 0)
);

