  CONSTRAINT "chk_subjects_employee_only_user" CHECK (subject_type = 'user' or employee_id is null),
  CONSTRAINT "chk_subjects_shared_no_employee" CHECK (account_type = 'personal' or employee_id is null),
  CONSTRAINT "chk_subjects_identifier_lowercase" CHECK (identifier = lower(identifier)),
  CONSTRAINT "chk_subjects_sync_provenance" CHECK ((source in ('api', 'log')) = (sync_run_id is not null)),
  CONSTRAINT "chk_subjects_import_provenance" CHECK ((source = 'import') = (import_batch_id is not null))
