  CONSTRAINT "chk_license_assignments_connector_only" CHECK (source in ('api', 'log')),
  CONSTRAINT "chk_license_assignments_sync_provenance" CHECK ((source in ('api', 'log')) = (sync_run_id is not null)),
  CONSTRAINT "chk_license_assignments_import_provenance" CHECK ((source = 'import') = (import_batch_id is not null))
);

CREATE TABLE "usage_records" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "license_plan_id" bigint NOT NULL,
  "subject_id" bigint,
  "metric" usage_metric NOT NULL,
  "period_start" date NOT NULL,
  "period_end" date NOT NULL,
  "quantity" numeric(20,4) NOT NULL,
  "source" data_source NOT NULL,
  "sync_run_id" bigint,
  "import_batch_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_usage_records_period" CHECK (period_end >= period_start),
  CONSTRAINT "chk_usage_records_quantity" CHECK (quantity >= 0),
  CONSTRAINT "chk_usage_records_connector_only" CHECK (source in ('api', 'log')),
  CONSTRAINT "chk_usage_records_active_subjects_aggregate" CHECK (metric <> 'active_subjects' or subject_id is null),
  CONSTRAINT "chk_usage_records_active_days" CHECK (metric <> 'active_days' or (subject_id is not null and quantity <= period_end - period_start + 1)),
  CONSTRAINT "chk_usage_records_whole_counts" CHECK (metric not in ('active_subjects', 'active_days', 'peak_concurrent') or quantity = trunc(quantity)),
  CONSTRAINT "chk_usage_records_sync_provenance" CHECK ((source in ('api', 'log')) = (sync_run_id is not null)),
  CONSTRAINT "chk_usage_records_import_provenance" CHECK ((source = 'import') = (import_batch_id is not null))
);

