  "active_minutes" int,
  "product_id" bigint,
  "period_start" date NOT NULL,
  "period_end" date NOT NULL,
  "days_used" int NOT NULL,
  "last_used_at" timestamptz,
  "source" data_source NOT NULL DEFAULT 'api',
  "sync_run_id" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_employee_app_usage_period" CHECK (period_end >= period_start),
  CONSTRAINT "chk_employee_app_usage_days" CHECK (days_used >= 0 and days_used <= period_end - period_start + 1),
  CONSTRAINT "chk_employee_app_usage_minutes" CHECK (active_minutes is null or active_minutes >= 0),
  CONSTRAINT "chk_employee_app_usage_identity_lowercase" CHECK (bca_identity = lower(bca_identity)),
  CONSTRAINT "chk_employee_app_usage_source" CHECK (source = 'api')
);

CREATE TABLE "budget_plans" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "org_unit_id" bigint NOT NULL,
  "fiscal_year" int NOT NULL,
  "period_from" date NOT NULL,
  "period_to" date NOT NULL,
  "version_no" int NOT NULL,
  "note" text,
  "created_by" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_budget_plans_period" CHECK (period_to >= period_from),
  CONSTRAINT "chk_budget_plans_year" CHECK (extract(year from period_from) = fiscal_year and extract(year from period_to) = fiscal_year),
  CONSTRAINT "chk_budget_plans_month_start" CHECK (extract(day from period_from) = 1 and extract(day from period_to) = 1),
  CONSTRAINT "chk_budget_plans_version" CHECK (version_no > 0)
);

CREATE TABLE "budget_plan_lines" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "budget_plan_id" bigint NOT NULL,
  "org_unit_id" bigint NOT NULL,
  "license_name" varchar(200) NOT NULL,
  "is_shared" boolean NOT NULL DEFAULT false,
  "license_plan_id" bigint,
  "month" date NOT NULL,
  "planned_quantity" numeric(20,4) NOT NULL,
  "planned_amount" numeric(18,2) NOT NULL,
  "currency" char(3) NOT NULL,
  "superseded_at" timestamptz,
  "superseded_by_plan_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_budget_plan_lines_quantity" CHECK (planned_quantity >= 0),
  CONSTRAINT "chk_budget_plan_lines_amount" CHECK (planned_amount >= 0),
  CONSTRAINT "chk_budget_plan_lines_month_start" CHECK (extract(day from month) = 1),
  CONSTRAINT "chk_budget_plan_lines_superseded" CHECK ((superseded_at is null) = (superseded_by_plan_id is null))
);

CREATE TABLE "cost_allocations" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "accounting_period_id" bigint NOT NULL,
  "license_plan_id" bigint NOT NULL,
  "bucket" cost_bucket NOT NULL,
  "org_unit_id" bigint NOT NULL,
  "method" allocation_method NOT NULL,
  "basis_qty" numeric(20,4),
  "filled_days" int,
  "amount" numeric(18,2),
  "used_amount" numeric(18,2),
  "wasted_amount" numeric(18,2),
  "not_evaluated_amount" numeric(18,2),
  "computed_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_cost_allocations_basis" CHECK (basis_qty is null or basis_qty >= 0),
  CONSTRAINT "chk_cost_allocations_filled_days" CHECK (((method = 'per_seat') = (filled_days is not null)) and (filled_days is null or filled_days between 0 and 31)),
  CONSTRAINT "chk_cost_allocations_unknown" CHECK (amount is not null or (used_amount is null and wasted_amount is null and not_evaluated_amount is null)),
  CONSTRAINT "chk_cost_allocations_split" CHECK (amount is null or used_amount is null or wasted_amount is null or not_evaluated_amount is null or amount = used_amount + wasted_amount + not_evaluated_amount),
  CONSTRAINT "chk_cost_allocations_unallocated_unused" CHECK (bucket <> 'unallocated' or used_amount is null or used_amount = 0)
);

CREATE TABLE "expenses" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "expense_date" date NOT NULL,
  "service_from" date,
  "service_to" date,
  "amount" numeric(18,2) NOT NULL,
  "currency" char(3) NOT NULL,
  "license_plan_id" bigint NOT NULL,
  "org_unit_id" bigint NOT NULL,
  "description" text,
  "invoice_file_id" bigint,
  "accrual_schedule" jsonb,
  "source" data_source NOT NULL DEFAULT 'manual',
  "external_ref" varchar(200),
  "sync_run_id" bigint,
  "import_batch_id" bigint,
  "created_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_expenses_amount_not_zero" CHECK (amount <> 0),
  CONSTRAINT "chk_expenses_service_pair" CHECK ((service_from is null) = (service_to is null)),
  CONSTRAINT "chk_expenses_service_term" CHECK (service_to is null or service_to >= service_from),
  CONSTRAINT "chk_expenses_sync_provenance" CHECK ((source in ('api', 'log')) = (sync_run_id is not null)),
  CONSTRAINT "chk_expenses_import_provenance" CHECK ((source = 'import') = (import_batch_id is not null))
);

CREATE TABLE "accounting_periods" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "org_unit_id" bigint NOT NULL,
  "period_year" int NOT NULL,
  "period_month" int NOT NULL,
  "closed_at" timestamptz,
  "closed_by" bigint,
  CONSTRAINT "chk_accounting_periods_month" CHECK (period_month between 1 and 12)
);

CREATE TABLE "exchange_rates" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "from_currency" char(3) NOT NULL,
  "rate" numeric(18,8) NOT NULL,
  "effective_from" date NOT NULL,
  "declared_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_exchange_rates_rate" CHECK (rate > 0)
);

CREATE TABLE "detection_runs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "data_date" date NOT NULL,
  "inactivity_threshold_days" int NOT NULL DEFAULT 30,
  "rule_version" varchar(20) NOT NULL,
  "status" run_status NOT NULL DEFAULT 'running',
  "started_at" timestamptz NOT NULL DEFAULT (now()),
  "finished_at" timestamptz,
  CONSTRAINT "chk_detection_runs_finished" CHECK ((status = 'running') = (finished_at is null)),
  CONSTRAINT "chk_detection_runs_status" CHECK (status <> 'paused')
);

CREATE TABLE "detection_results" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "detection_run_id" bigint NOT NULL,
  "license_plan_id" bigint NOT NULL,
  "org_unit_id" bigint,
  "check_type" detection_check NOT NULL,
  "flagged_qty" numeric(20,4),
  "monthly_cost" numeric(18,2),
  "flagged_since" date,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_detection_results_unit" CHECK (check_type in ('inactive', 'leaver') or org_unit_id is not null),
  CONSTRAINT "chk_detection_results_flagged_qty" CHECK (flagged_qty is null or flagged_qty >= 0),
  CONSTRAINT "chk_detection_results_since" CHECK ((coalesce(flagged_qty, 0) > 0) = (flagged_since is not null))
);

CREATE TABLE "recommendations" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "license_plan_id" bigint NOT NULL,
  "target_plan_id" bigint,
  "org_unit_id" bigint,
  "detection_result_id" bigint,
  "type" recommendation_type NOT NULL,
  "title" varchar(300) NOT NULL,
  "description" text,
  "evidence" jsonb NOT NULL,
  "affected_qty" numeric(20,4),
  "estimated_yearly_saving" numeric(18,2),
  "actual_saving" numeric(18,2),
  "status" recommendation_status NOT NULL DEFAULT 'proposed',
  "rejection_reason" text,
  "contract_id" bigint,
  "due_date" date,
  "owner_id" bigint,
  "created_by" bigint NOT NULL,
  "decided_by" bigint,
  "decided_at" timestamptz,
  "done_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_recommendations_reject_reason" CHECK (status <> 'rejected' or rejection_reason is not null),
  CONSTRAINT "chk_recommendations_done" CHECK (status <> 'done' or (done_at is not null and actual_saving is not null)),
  CONSTRAINT "chk_recommendations_decided" CHECK ((status in ('accepted', 'rejected', 'done')) = (decided_at is not null)),
  CONSTRAINT "chk_recommendations_saving" CHECK (estimated_yearly_saving is null or estimated_yearly_saving >= 0),
  CONSTRAINT "chk_recommendations_target_plan" CHECK ((type = 'downgrade_plan') = (target_plan_id is not null)),
  CONSTRAINT "chk_recommendations_target_differs" CHECK (target_plan_id is null or target_plan_id <> license_plan_id)
);

CREATE TABLE "audit_logs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "actor_id" bigint,
  "action" varchar(50) NOT NULL,
  "entity_type" varchar(60) NOT NULL,
  "entity_id" bigint NOT NULL,
  "old_values" jsonb,
  "new_values" jsonb,
  "reason" text,
  "correlation_id" varchar(64),
  "ip_address" varchar(45),
  "occurred_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "data_overrides" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "entity_type" varchar(60) NOT NULL,
  "entity_id" bigint NOT NULL,
  "field_name" varchar(60) NOT NULL,
  "original_value" text,
  "override_value" text NOT NULL,
  "reason" text NOT NULL,
  "overridden_by" bigint NOT NULL,
  "overridden_at" timestamptz NOT NULL DEFAULT (now()),
  "reverted_at" timestamptz
);

